import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.DfDAiEgj.js";const f=JSON.parse('{"title":"移民","description":"","frontmatter":{},"headers":[],"relativePath":"ai-job/Layoff.md","filePath":"ai-job/Layoff.md","lastUpdated":null}'),i={name:"ai-job/Layoff.md"};function h(o,a,l,p,s,u){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="移民" tabindex="-1">移民 <a class="header-anchor" href="#移民" aria-label="Permalink to &quot;移民&quot;">​</a></h1><h2 id="签证" tabindex="-1">签证 <a class="header-anchor" href="#签证" aria-label="Permalink to &quot;签证&quot;">​</a></h2><p>如果直接出去的话，只能使用H1B签证，这是一个短期的工作签证，一生中能申请2次，每次3年，如果绿卡排期的时候可以无限申请。另外还有一个外派高管签证，这个不介绍了。[2]</p><p>申请H1B签证，需要企业针对一个岗位和人员提出。有几个硬指标：</p><ul><li>岗位是找不到合适的美国公民</li><li>工资达到劳工局标准</li><li>你符合这个岗位要求</li></ul><h2 id="绿卡" tabindex="-1">绿卡 <a class="header-anchor" href="#绿卡" aria-label="Permalink to &quot;绿卡&quot;">​</a></h2><h3 id="美国" tabindex="-1">美国 <a class="header-anchor" href="#美国" aria-label="Permalink to &quot;美国&quot;">​</a></h3><p>世界上最不缺科研人员的美国。它对引进人才的标准是什么呢？美国没有一个量化的打分表，但是统计美国近些年引进的中国科研移民，在EB1a领域，即Alien with extraordinary ability（拥有极其杰出能力和成就的外国人，这种绿卡在英语圈又称作“Einstein Visa”，即爱因斯坦绿卡），我想应该勉强符合本题对“人才”的定义，其要求如下：</p><ol><li>正在从事科研领域的工作</li><li>发表过10篇以上SCI论文（只要挂名就可以，不要求一作）。</li><li>论文被引用累计超过500次（只要挂名就可以，不要求一作）。</li><li>审过其他人的稿子数次。</li></ol><p>上述要求，甚至不包含博士学位，毕业院校世界排名，以及你人现在在哪里。事实上，只要你关注过任何美国移民律师的公众号成功案例，就会发现，该绿卡将近一半的人，申请的时候都是人在中国，某医院/科研院所/大学的职员/教授/博后。值得一提的是，美国的杰出人才绿卡是一人通过，全家移民。</p><p>上述要求勉强达标的科研人员，据我的了解，在国内能获得的待遇就是中山大学炮灰型研究员，实际到手月入1万3，用过即弃，三年合同到期学校直接解聘走人。[3]</p><h2 id="生活水平" tabindex="-1">生活水平 <a class="header-anchor" href="#生活水平" aria-label="Permalink to &quot;生活水平&quot;">​</a></h2><p>在旧金山湾区工作生活，年收入 13 万刀左右是个什么水平？ - 安大明白的回答 - 知乎 <a href="https://www.zhihu.com/question/50662770/answer/122675446" target="_blank" rel="noreferrer">https://www.zhihu.com/question/50662770/answer/122675446</a></p><h2 id="裁员-pip制度" tabindex="-1">裁员 PIP制度 <a class="header-anchor" href="#裁员-pip制度" aria-label="Permalink to &quot;裁员 PIP制度&quot;">​</a></h2><p>PIP制度，就是悬在外国雇员头上的一柄达摩克利斯之剑。[1]</p><p>PIP，全称performance improvement plan，即绩效提升计划。公司会要求被PIP的雇员在一段时间内提高表现，如果不能达到标准，就会被炒掉。而实际上，这一标准一般都无法达到，PIP也就成了解雇员工的“潜规则”。</p><p>对于外国雇员来说，大部分拿的是H1B签证（工作签证），一旦因PIP被开掉，就会失去在美国的合法身份，必须尽快离境，面临不得不回国的情况。</p><p>据悉，亚马逊每年都会有两次大规模的员工绩效评估，绩效在后10%的员工都有可能被PIP。而一直标榜人性化的Facebook，每年被PIP的员工数量也达到了10%以上。</p><p>如何看待亚马逊 AI 李沐团队大批人员离职? <a href="https://www.zhihu.com/question/392035070/answer/1227368673" target="_blank" rel="noreferrer">https://www.zhihu.com/question/392035070/answer/1227368673</a></p><p>地平线创始人余凯回应“大裁员” <a href="https://plumwine.me/news652606/" target="_blank" rel="noreferrer">https://plumwine.me/news652606/</a></p><p>国外发达国家码农是真混得好么? - CS GOGOGO的回答 - 知乎 <a href="https://www.zhihu.com/question/38972340/answer/1974258884" target="_blank" rel="noreferrer">https://www.zhihu.com/question/38972340/answer/1974258884</a></p><p>Uber关掉AI实验室： <a href="http://m.thepaper.cn/rss_newsDetail_7461293?from=sina" target="_blank" rel="noreferrer">http://m.thepaper.cn/rss_newsDetail_7461293?from=sina</a> [1]: <a href="https://zhuanlan.zhihu.com/p/83886539" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/83886539</a> [2]: <a href="https://zhuanlan.zhihu.com/p/33840674" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/33840674</a> [3]: <a href="https://www.zhihu.com/question/483935599/answer/2110594874" target="_blank" rel="noreferrer">https://www.zhihu.com/question/483935599/answer/2110594874</a></p>',22)])])}const w=e(i,[["render",h]]);export{f as __pageData,w as default};
